import{_ as o,o as a,c as t,ae as r}from"./chunks/framework.DK2I2JUh.js";const p=JSON.parse('{"title":"The SafeC Book","description":"","frontmatter":{},"headers":[],"relativePath":"book/index.md","filePath":"book/index.md"}'),s={name:"book/index.md"};function n(i,e,h,c,d,l){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="the-safec-book" tabindex="-1">The SafeC Book <a class="header-anchor" href="#the-safec-book" aria-label="Permalink to &quot;The SafeC Book&quot;">​</a></h1><p>Welcome to <em>The SafeC Book</em> — a from-scratch, worked-example tutorial for learning SafeC as a language, in the tradition of Kernighan &amp; Ritchie&#39;s <em>The C Programming Language</em> and <em>The Rust Programming Language</em>. Where those books teach C&#39;s small, orthogonal core and Rust&#39;s ownership model through running examples rather than dry enumeration, this book does the same for SafeC: a C superset whose one big idea is the <strong>region system</strong> — compile-time-tracked memory provenance (<code>&amp;stack</code>, <code>&amp;heap</code>, <code>&amp;arena&lt;R&gt;</code>, <code>&amp;static</code>) that catches use-after-free and aliasing bugs before your program ever runs, at zero runtime cost.</p><p>This is a tutorial, not a reference. It introduces features in the order you need them to write real programs, with complete, compilable examples at every step — every code block in this book has been compiled and, where it produces output, run, against the real <code>safec</code> compiler. For exhaustive detail on any single feature (every operator&#39;s precedence, every stdlib function&#39;s signature), see the <a href="/safec-docs/reference/types.html">Reference</a> and <a href="/safec-docs/stdlib/">Standard Library</a> sections instead — this book will link to them at the point where you&#39;re ready for that depth.</p><h2 id="who-this-book-is-for" tabindex="-1">Who this book is for <a class="header-anchor" href="#who-this-book-is-for" aria-label="Permalink to &quot;Who this book is for&quot;">​</a></h2><p>You should already know how to program in <em>some</em> C-family language (C, C++, Java, Go, Rust — the exact one doesn&#39;t matter much) and be comfortable with pointers as a concept, even if a specific language kept them out of your hands. This book does not re-teach &quot;what is a variable&quot; or &quot;what is a loop&quot; from first principles the way a total-beginner programming book would — Chapter 3 moves through those quickly, as a refresher of SafeC&#39;s specific syntax rather than the underlying concepts. If you know C reasonably well, most of Chapters 1–4 will be fast going; the real new material starts at Chapter 5.</p><h2 id="how-to-read-this-book" tabindex="-1">How to read this book <a class="header-anchor" href="#how-to-read-this-book" aria-label="Permalink to &quot;How to read this book&quot;">​</a></h2><p>Chapters are meant to be read in order — each one builds on syntax and vocabulary from the ones before it, the same way <em>The Rust Programming Language</em>&#39;s chapters do. If you already know C well, Chapter 5 (regions) is the one chapter you shouldn&#39;t skip: it&#39;s the one genuinely new idea in the whole language, and everything from Chapter 6 onward assumes you have it.</p><ol><li><a href="/safec-docs/book/ch01-getting-started.html">Getting Started</a> — installing the toolchain, <code>safeguard new</code>, compiling and running your first program</li><li><a href="/safec-docs/book/ch02-first-program.html">A First Program</a> — a complete temperature-converter CLI tool, introducing I/O and the edit-compile-run loop</li><li><a href="/safec-docs/book/ch03-common-concepts.html">Common Concepts</a> — variables, types, operators, control flow</li><li><a href="/safec-docs/book/ch04-functions.html">Functions</a> — declarations, parameters, overloading, <code>pure</code></li><li><a href="/safec-docs/book/ch05-understanding-regions.html">Understanding Regions</a> — the region system: <code>&amp;stack</code>, <code>&amp;heap</code>, <code>&amp;arena&lt;R&gt;</code>, <code>&amp;static</code>, and the borrow rules</li><li><a href="/safec-docs/book/ch06-structs-and-methods.html">Structs and Methods</a> — defining types, methods, operator overloading</li><li><a href="/safec-docs/book/ch07-enums-and-match.html">Enums, Unions, and Match</a> — tagged unions and exhaustive pattern matching</li><li><a href="/safec-docs/book/ch08-error-handling.html">Error Handling</a> — optionals, <code>try</code>, <code>defer</code>/<code>errdefer</code>, no exceptions</li><li><a href="/safec-docs/book/ch09-final-project.html">A Final Project: a Key-Value Store</a> — putting it all together in a larger program</li></ol><p>Let&#39;s get started.</p>',9)])])}const f=o(s,[["render",n]]);export{p as __pageData,f as default};
